<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from"vue";import{ElMessage}from"element-plus";import{listTemplates,saveTemplateVersion,type Template}from"@/api/business";const rows=ref<Template[]>([]),selectedId=ref<number>(),m=reactive({title:"获奖证书",size:34,color:"#1f2937",number:true,watermark:true});const selected=computed(()=>rows.value.find(x=>x.id===selectedId.value));async function load(){rows.value=await listTemplates();if(!selectedId.value&&rows.value.length)selectedId.value=rows.value[0].id}watch(selected,template=>{const c=template?.latest_version?.canvas as any;if(c)Object.assign(m,c)});async function save(){if(!selectedId.value)return;const result=await saveTemplateVersion(selectedId.value,{...m});ElMessage.success(`已保存模板版本 v${result.number}`);await load()}onMounted(load);</script>
<template><div class="editor"><aside><h3>模板库</h3><el-select v-model="selectedId" class="full"><el-option v-for="t in rows" :key="t.id" :label="`${t.name} · ${t.department_name}`" :value="t.id"/></el-select><el-divider/><h3>图层</h3><el-button class="full">添加文本</el-button><el-button class="full">上传背景</el-button><el-button class="full">添加公章位</el-button></aside><main><div class="canvas"><div class="title" :style="{fontSize:m.size+'px',color:m.color}">{{m.title}}</div><p>测试专用团队<br>荣获 一等奖</p><small v-if="m.number">2026-AC-00000001</small><b v-if="m.watermark">测试专用</b></div></main><aside><h3>属性</h3><el-form label-position="top"><el-form-item label="标题"><el-input v-model="m.title"/></el-form-item><el-form-item label="字号"><el-slider v-model="m.size" :min="16" :max="56"/></el-form-item><el-form-item label="颜色"><el-color-picker v-model="m.color"/></el-form-item><el-checkbox v-model="m.number">显示正文编号</el-checkbox><el-checkbox v-model="m.watermark">显示编号水印</el-checkbox><el-button type="primary" class="full save" :disabled="!selectedId" @click="save">保存新版本</el-button></el-form></aside></div></template>
<style scoped>.editor{display:grid;grid-template-columns:230px 1fr 270px;height:calc(100vh - 110px);background:#f5f7fa}.editor aside{background:#fff;padding:18px;border-right:1px solid #e5e7eb}.editor aside:last-child{border:0;border-left:1px solid #e5e7eb}.editor main{display:grid;place-items:center;overflow:auto}.canvas{position:relative;width:min(840px,88%);aspect-ratio:1.414;background:#fff;border:1px solid #ddd;box-shadow:0 8px 24px rgb(0 0 0 / 8%)}.title{text-align:center;margin-top:12%;font-weight:700}.canvas p{text-align:center;margin-top:10%;font-size:22px;line-height:2}.canvas small{position:absolute;left:8%;bottom:8%}.canvas b{position:absolute;right:8%;bottom:8%;color:#bbb}.full{width:100%;margin-bottom:10px}.save{margin-top:22px}@media(max-width:900px){.editor{grid-template-columns:1fr;height:auto}.editor aside{border:0;border-bottom:1px solid #ddd}.editor main{min-height:420px}}</style>
